import re
from decimal import Decimal

_MAX_AMOUNT = Decimal("1000000.00")
_PLAIN_DECIMAL = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)")


def _to_decimal(value):
    if isinstance(value, bool):
        raise ValueError("boolean is not an amount")
    if isinstance(value, Decimal):
        return value
    if isinstance(value, int):
        return Decimal(value)
    if isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError(f"not a plain decimal string: {value!r}")
        return Decimal(value)
    raise ValueError(f"unsupported amount type: {type(value).__name__}")


def parse_amount_cents(value):
    """Validate an amount and return it as an exact integer number of cents.

    Uses only exact Decimal comparisons and tuple inspection, so the active
    decimal context is never consulted and nothing is rounded.
    """
    d = _to_decimal(value)
    if not d.is_finite():
        raise ValueError("amount must be finite")
    if d <= 0:
        raise ValueError("amount must be positive")
    if d > _MAX_AMOUNT:
        raise ValueError("amount exceeds 1000000.00")
    _sign, digits, exponent = d.as_tuple()
    digits = list(digits)
    while digits[-1] == 0:  # d is nonzero, so a nonzero digit remains
        digits.pop()
        exponent += 1
    if exponent < -2:
        raise ValueError("amount is not exactly representable in cents")
    coefficient = int("".join(map(str, digits)))
    return coefficient * 10 ** (exponent + 2)


def cents_to_amount(cents):
    """Return a non-negative integer number of cents as a Decimal with exponent -2."""
    return Decimal(f"{cents // 100}.{cents % 100:02d}")


def parse_amount(value):
    return cents_to_amount(parse_amount_cents(value))


def format_amount(value):
    return format(value, ".2f")
